pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz at least one parameter; version() takes no parameters, but we must accept fuzzed inputs
    // so include a dummy fuzzed parameter that does not affect contract state — the property must hold for all inputs
    function testFuzz_property(uint256 dummy) public {
        // keep dummy wide — no vm.assume needed

        // call version and capture its return via try/catch to observe behavior for both reference and mutant
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        // The universal property: the reference always returns the literal "1.0.0" (and does not revert)
        // The mutant changes the returned string for some inputs; assert that the call succeeded and returned "1.0.0"
        assertTrue(ok && (keccak256(bytes(v)) == keccak256(bytes("1.0.0"))));
    }
}

