pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address which is the deciding value: whether it equals the stored depositorAccount
    function testFuzz_property(address caller) public {
        // Keep domain wide; no restrictive assumes.

        // We will set c.depositorAccount via low-level storage if possible by making the contract itself set it.
        // However the reference contract declares `address public depositorAccount;` uninitialized in constructor,
        // so its default is address(0). The general rule: only the address stored in depositorAccount may call.
        // To exercise difference we fuzz `caller` and attempt the call as that caller.

        // Prepare calldata for setL1BlockValues with arbitrary (fuzz) values; the reference should allow exactly when
        // caller == depositorAccount. Because depositorAccount is public and defaults to zero, we first test two scenarios:
        // 1) leave depositorAccount as zero (unchanged) and call as address(0) — allowed by reference, rejected by mutant unless constant is zero.
        // 2) if caller != address(0), we first set depositorAccount to caller by directly invoking via test contract using
        //    a low-level trick: since depositorAccount is public and no setter exists, we cannot change it externally in reference.
        // Therefore the universal property we assert is: after attempting setL1BlockValues from `caller`, the call succeeds iff caller == c.depositorAccount().

        // Make the call as `caller` and observe whether it succeeded (did not revert). Use try/catch to capture revert.
        bool ok;
        // Prepare arbitrary params
        uint64 number = 1;
        uint64 timestamp = 2;
        uint256 basefee = 3;
        bytes32 hash = bytes32(uint256(4));
        uint64 sequenceNumber = 5;
        bytes32 batcherHash = bytes32(uint256(6));
        uint256 l1FeeOverhead = 7;
        uint256 l1FeeScalar = 8;

        // perform the call as the fuzzed caller
        vm.prank(caller);
        try c.setL1BlockValues(
            number,
            timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant: reference accepts the call exactly when caller equals depositorAccount stored in contract.
        // Read depositorAccount via its public getter
        address stored = c.depositorAccount();

        // Exactly one assertion: the reference contract satisfies for ALL inputs that ok == (caller == stored).
        assertTrue(ok == (caller == stored));
    }
}
